import{_ as c,C as a,o as l,c as d,j as t,a as h,G as r,a2 as i}from"./chunks/framework.BgSoyxN5.js";const v=JSON.parse(`{"title":"Free Stock Check: Stock Verdict, Quality, Risk, Ownership, and Alerts","description":"Run a free TickerForge stock check to review a ticker's verdict, business quality, valuation, risk, fund moves, insider activity, timing, and alerts.","frontmatter":{"title":"Free Stock Check: Stock Verdict, Quality, Risk, Ownership, and Alerts","description":"Run a free TickerForge stock check to review a ticker's verdict, business quality, valuation, risk, fund moves, insider activity, timing, and alerts.","aside":false},"headers":[],"relativePath":"stock-widget.md","filePath":"stock-widget.md","lastUpdated":1785053778000}`),u={name:"stock-widget.md"};function p(k,e,f,g,m,y){const o=a("TickerForgeComplianceDisclaimer"),s=a("TickerForgeTrustBlock"),n=a("TickerForgeStockWidget");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"free-stock-analysis-widget",tabindex:"-1"},[h("Free Stock Analysis Widget "),t("a",{class:"header-anchor",href:"#free-stock-analysis-widget","aria-label":'Permalink to "Free Stock Analysis Widget"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Enter a ticker or company name to run a structured TickerForge stock check directly in your browser. The widget brings together the stock verdict, business quality, valuation, financial strength, risk, institutional activity, insider transactions, timing, and a follow-up path for alerts or portfolio review.",-1)),e[2]||(e[2]=t("p",null,"Use it when you want to answer a practical first-screen question: is this ticker worth deeper research, should it be monitored, or should the setup wait for better evidence?",-1)),r(o),r(s,{kind:"stock"}),e[3]||(e[3]=i('<h2 id="try-this-workflow" tabindex="-1">Try This Workflow <a class="header-anchor" href="#try-this-workflow" aria-label="Permalink to &quot;Try This Workflow&quot;">​</a></h2><p>Try a ticker such as <code>NVDA</code>, <code>TSM</code>, or a natural-language request like <code>show Microsoft</code>. Start with the compact verdict, then open the supporting evidence behind it. If the result is interesting, continue to email or Telegram to save the context, enable alerts, or compare the stock with <a href="/portfolio-analysis">Portfolio Analysis</a>.</p><p>Educational decision-support software. Not financial advice.</p>',3)),r(n,{"api-base":"https://api.ticker-forge.com"}),e[4]||(e[4]=i('<h2 id="free-check-then-choose-your-next-step" tabindex="-1">Free Check, Then Choose Your Next Step <a class="header-anchor" href="#free-check-then-choose-your-next-step" aria-label="Permalink to &quot;Free Check, Then Choose Your Next Step&quot;">​</a></h2><p>The stock check is free. After the verdict, TickerForge asks what you want to do next: make a one-time decision, track the stock, watch entry improvement, or follow insider and fund activity.</p><p>Free users can continue with basic Smart Alerts for up to 5 tracked stocks. If you choose Standard access, the widget records the product context and sends you to the <a href="/pricing">Pricing page</a>, where current paid access is handled through Telegram Stars.</p><p>If you leave an email or continue in Telegram, TickerForge can connect the stock check to your <a href="/workspace/">Workspace</a>. The workspace is the personal area for returning to saved stock checks, alert status, portfolio tools, and follow-up workflows without starting from zero every time.</p><h2 id="what-the-stock-verdict-includes" tabindex="-1">What the Stock Verdict Includes <a class="header-anchor" href="#what-the-stock-verdict-includes" aria-label="Permalink to &quot;What the Stock Verdict Includes&quot;">​</a></h2><h3 id="stockverdict-summary" tabindex="-1">StockVerdict Summary <a class="header-anchor" href="#stockverdict-summary" aria-label="Permalink to &quot;StockVerdict Summary&quot;">​</a></h3><p>The summary gives you the fastest read on the company. It combines the current TickerForge verdict with business quality, entry timing, technical setup, and the most important risks. Use it as a research starting point, not as an automatic buy or sell instruction.</p><h3 id="financial-details" tabindex="-1">Financial Details <a class="header-anchor" href="#financial-details" aria-label="Permalink to &quot;Financial Details&quot;">​</a></h3><p>Open <strong>Business Data</strong> to examine revenue, profitability, cash flow, debt, valuation, and balance-sheet strength. These figures help explain whether reported growth is supported by durable economics. For help interpreting the underlying statements, read <a href="/blog/how-to-read-financial-statements">How to Read Financial Statements</a>.</p><h3 id="business-analysis" tabindex="-1">Business Analysis <a class="header-anchor" href="#business-analysis" aria-label="Permalink to &quot;Business Analysis&quot;">​</a></h3><p>TickerForge evaluates more than recent price performance. The business layer considers operating quality, financial resilience, growth characteristics, valuation, and company-specific risk. It is designed to distinguish a strong business at an awkward entry point from a weak business experiencing temporary momentum.</p><h3 id="top-fund-moves" tabindex="-1">Top Fund Moves <a class="header-anchor" href="#top-fund-moves" aria-label="Permalink to &quot;Top Fund Moves&quot;">​</a></h3><p>Institutional data shows how tracked funds changed their reported positions. You can review notable new, increased, reduced, or exited holdings and compare fund behavior with the stock&#39;s price trend. Because 13F filings are delayed, fund moves provide context rather than a real-time trading signal. For the screening workflow around this layer, read the <a href="/blog/smart-money-stock-screener">Smart Money Stock Screener guide</a>.</p><h3 id="insider-activity" tabindex="-1">Insider Activity <a class="header-anchor" href="#insider-activity" aria-label="Permalink to &quot;Insider Activity&quot;">​</a></h3><p>The insider view highlights reported open-market purchases and sales by executives, directors, and other insiders. TickerForge separates higher-signal transactions from routine compensation activity where the available data allows it. The <a href="/blog/insider-buying-screener">Insider Buying Screener guide</a> explains why insider activity should support a thesis rather than replace business analysis.</p><h3 id="portfolio-builder" tabindex="-1">Portfolio Builder <a class="header-anchor" href="#portfolio-builder" aria-label="Permalink to &quot;Portfolio Builder&quot;">​</a></h3><p>A stock idea is only useful if it fits into a stronger portfolio structure. After reviewing the verdict, fundamentals, fund moves, and insider activity, use the <a href="/portfolio-builder">Portfolio Builder</a> to see how TickerForge screens candidates, applies quality and risk rules, checks concentration, and proposes a diversified virtual portfolio.</p><h2 id="continue-research-in-tickerforge" tabindex="-1">Continue Research in TickerForge <a class="header-anchor" href="#continue-research-in-tickerforge" aria-label="Permalink to &quot;Continue Research in TickerForge&quot;">​</a></h2><p>Use the widget for a quick company investigation, then move from a single-stock view to portfolio-level thinking with the <a href="/portfolio-builder">Portfolio Builder</a>, <a href="/portfolio-analysis">Portfolio Analysis</a>, and the access levels listed on the <a href="/pricing">Pricing page</a>.</p><p>For ongoing monitoring, continue in Telegram. TickerForge tracking can watch selected stocks and surface relevant changes without requiring you to repeat the full analysis every day.</p><p><strong><a href="https://t.me/TickerForgeBot?start=src_stock_widget_landing" target="_blank" rel="noreferrer">Open TickerForge in Telegram and track a stock</a></strong></p><h2 id="related-read-next" tabindex="-1">Related / Read Next <a class="header-anchor" href="#related-read-next" aria-label="Permalink to &quot;Related / Read Next&quot;">​</a></h2><ul><li><a href="/stocks/">Browse stock deep dives</a> — compare business narratives, catalysts, and risks across AI infrastructure stocks.</li><li><a href="/methodology/tickerforge-score">TickerForge Score methodology</a> — see how business quality and valuation signals are structured.</li><li><a href="/methodology/risk-score">Stock Risk Score methodology</a> — understand how financial fragility and downside signals are evaluated.</li><li><a href="/blog/stock-screener-with-alerts">Stock Screener With Alerts</a> — learn how to monitor verdict, entry, risk, insider, and fund changes after screening.</li><li><a href="/methodology/dcf-model">DCF valuation methodology</a> — review how TickerForge estimates intrinsic value.</li><li><a href="/methodology/tickerforge-tech-entry">Technical Entry methodology</a> — see how trend and timing context are interpreted.</li><li><a href="/import-portfolio">Import a portfolio</a> — test how a stock idea affects your existing concentration and market sensitivity.</li></ul><p>TickerForge provides algorithmic research and educational diagnostics, not financial advice. Always verify the underlying data and make decisions according to your own objectives and risk tolerance.</p>',24))])}const b=c(u,[["render",p]]);export{v as __pageData,b as default};
